components.css:
.ds-btn-primary { display: inline-block; background-color: #d42274; color: #ffffff; border: 1px solid #d42274; border-radius: 0.375rem; padding: 0.375rem 0.75rem; font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1.125rem; font-weight: 400; line-height: 1.5; cursor: pointer; text-decoration: none; transition: background-color 0.15s ease-in-out, border-color 0.15s ease-in-out; }
.ds-btn-primary:hover { background-color: #b31d63; border-color: #b31d63; }
.ds-btn-primary:focus-visible { background-color: #b31d63; border-color: #b31d63; outline: 2px solid #d42274; outline-offset: 2px; }
.ds-btn-primary:active { background-color: #9e1a56; border-color: #9e1a56; }
@media (prefers-reduced-motion: reduce) { .ds-btn-primary { transition: none; } }

.ds-card { background-color: #ffffff; border: 1px solid rgba(33,37,41,0.125); border-radius: 0.375rem; overflow: hidden; display: flex; flex-direction: column; }
.ds-card-img-wrap { overflow: hidden; }
.ds-card-img { width: 100%; height: auto; display: block; filter: grayscale(100%); transition: filter 0.2s ease-in-out; }
.ds-card:hover .ds-card-img { filter: grayscale(70%); }
.ds-card-body { padding: 1.125rem; flex: 1; }
.ds-card-title { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1.125rem; font-weight: 700; color: #212529; margin: 0 0 0.5rem; }
.ds-card-text { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1rem; color: #495057; margin: 0; line-height: 1.5; }
@media (prefers-reduced-motion: reduce) { .ds-card-img { transition: none; } }

.ds-nav { background-color: rgba(255,255,255,0.98); padding: 0.5rem 1rem; display: flex; align-items: center; gap: 1.5rem; }
.ds-nav-brand { text-decoration: none; flex-shrink: 0; }
.ds-nav-avatar { width: 42px; height: 42px; border-radius: 50%; background-color: #d0d0d0; }
.ds-nav-links { display: flex; gap: 1rem; align-items: center; }
.ds-nav-link { color: #212529; text-decoration: none; font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 0.875rem; font-weight: 700; transition: color 0.15s ease-in-out; padding: 0.25rem 0; }
.ds-nav-link:hover { color: #495057; }
.ds-nav-link--active { color: #d42274; }
.ds-nav-link:focus-visible { outline: 2px solid #d42274; outline-offset: 2px; border-radius: 0.25rem; }
@media (prefers-reduced-motion: reduce) { .ds-nav-link { transition: none; } }

.ds-entrylist { position: relative; padding-left: 2.25rem; }
.ds-entrylist::before { position: absolute; top: 1.7rem; bottom: 0; left: 1.1rem; width: 1px; content: ''; background: linear-gradient(to top, rgba(33,37,41,0) 0%, rgba(33,37,41,1) 4rem, rgba(33,37,41,1) 100%); }
.ds-entry-item { position: relative; margin-bottom: 2rem; }
.ds-entry-item::before { position: absolute; top: 0.45rem; left: -2.25rem; width: 0.625rem; height: 0.625rem; content: ''; background-color: #d42274; border-radius: 50%; transform: translateX(50%); }
.ds-entry-title { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1.125rem; font-weight: 700; color: #212529; margin: 0 0 0.25rem; }
.ds-entry-meta { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 0.875rem; color: #495057; margin: 0 0 0.5rem; }
.ds-entry-body { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1.125rem; color: #212529; margin: 0; line-height: 1.5; }

.ds-footer { background-color: #d42274; padding: 3.375rem 1.5rem 2rem; color: #ffffff; }
.ds-footer-inner { display: flex; gap: 3rem; flex-wrap: wrap; margin-bottom: 2rem; }
.ds-footer-section { flex: 1; min-width: 200px; }
.ds-footer-heading { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1.125rem; font-weight: 700; color: #ffffff; margin: 0 0 0.75rem; }
.ds-footer-body { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 1.125rem; color: #ffffff; margin: 0; line-height: 1.5; }
.ds-footer-link { color: #ffffff; text-decoration: none; }
.ds-footer-link:hover { text-decoration: underline; }
.ds-footer-link:focus-visible { outline: 2px solid #ffffff; outline-offset: 2px; border-radius: 0.25rem; }
.ds-footer-list { list-style: none; padding: 0; margin: 0; }
.ds-footer-list li { margin-bottom: 0.25rem; }
.ds-footer-legal { font-family: 'IBM Plex Sans', system-ui, sans-serif; font-size: 0.875rem; color: rgba(255,255,255,0.8); margin: 0; }
